import "server-only";
import Razorpay from "razorpay";
import { createHmac, timingSafeEqual } from "node:crypto";

let client: Razorpay | null = null;

export function razorpayConfigured() {
  return Boolean(process.env.RAZORPAY_KEY_ID && process.env.RAZORPAY_KEY_SECRET);
}

export function razorpay() {
  if (!razorpayConfigured()) throw new Error("Razorpay keys are not configured");
  client ??= new Razorpay({ key_id: process.env.RAZORPAY_KEY_ID!, key_secret: process.env.RAZORPAY_KEY_SECRET! });
  return client;
}

function safeEqualHex(expected: string, received: string) {
  const a = Buffer.from(expected, "utf8");
  const b = Buffer.from(received, "utf8");
  return a.length === b.length && timingSafeEqual(a, b);
}

/** Checkout success signature: HMAC_SHA256(order_id + "|" + payment_id, key_secret). */
export function verifyPaymentSignature(orderId: string, paymentId: string, signature: string) {
  const expected = createHmac("sha256", process.env.RAZORPAY_KEY_SECRET!).update(`${orderId}|${paymentId}`).digest("hex");
  return safeEqualHex(expected, signature);
}

/** Webhook signature: HMAC_SHA256(raw request body, webhook_secret). */
export function verifyWebhookSignature(rawBody: string, signature: string) {
  const secret = process.env.RAZORPAY_WEBHOOK_SECRET;
  if (!secret) return false;
  const expected = createHmac("sha256", secret).update(rawBody).digest("hex");
  return safeEqualHex(expected, signature);
}

export type PaymentSummary = {
  method: string;
  details: Record<string, string | number | null>;
};

/** Normalise a Razorpay payment entity into what we store on the order (no card numbers). */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function summarizePayment(p: any): PaymentSummary {
  const details: Record<string, string | number | null> = {};
  if (p.bank) details.bank = p.bank;
  if (p.wallet) details.wallet = p.wallet;
  if (p.vpa) details.upiHandle = String(p.vpa).replace(/^[^@]+/, "***");
  if (p.card) {
    details.cardNetwork = p.card.network ?? null;
    details.cardType = p.card.type ?? null;
    details.cardIssuer = p.card.issuer ?? null;
    details.cardLast4 = p.card.last4 ?? null;
  }
  if (p.emi) {
    details.emiIssuer = p.emi.issuer ?? null;
    details.emiTenureMonths = p.emi.duration ? Number(p.emi.duration) : null;
    details.emiRate = p.emi.rate ?? null;
    details.emiType = p.emi.type ?? null;
  }
  if (p.provider) details.provider = p.provider; // cardless_emi / paylater partner, e.g. bajaj, hdfc
  if (p.emi_plan) details.emiPlan = JSON.stringify(p.emi_plan);
  return { method: p.method, details };
}
